:root {
  --ink: #263238;
  --muted: #64747a;
  --paper: #fffdf7;
  --line: #dce3dc;
  --coral: #ed7465;
  --sun: #f5c84b;
  --sky: #78bfd0;
  --mint: #9bcfb7;
  --deep-teal: #286b69;
}

* {
  box-sizing: border-box;
}

.puzzle-pass {
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.pass-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
}

.mark {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 10px;
  background: var(--coral);
  color: var(--paper);
  font-size: 20px;
}

.title-block {
  flex: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.2px;
}

h1 {
  margin: 0;
  font-size: 19px;
  line-height: 1.1;
}

.status {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--deep-teal);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.6px;
}

.pass-body {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 16px;
}

.details {
  display: grid;
  flex: 1;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.detail-item {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.detail-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.8px;
}

.detail-item strong {
  font-size: 14px;
  line-height: 1.2;
}

.wide-detail {
  grid-column: 1 / -1;
  padding-top: 9px;
  border-top: 1px dashed var(--line);
}

.puzzle-preview {
  display: grid;
  width: 104px;
  height: 104px;
  grid-template-columns: repeat(2, 1fr);
  gap: 5px;
  margin: 0;
  padding: 7px;
  border-radius: 16px;
  background: var(--ink);
}

.piece {
  border-radius: 10px 4px 10px 4px;
}

.piece-coral {
  background: var(--coral);
}

.piece-sun {
  background: var(--sun);
}

.piece-sky {
  background: var(--sky);
}

.piece-mint {
  background: var(--mint);
}

.pass-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
  background: var(--mint);
}

.claim-code {
  color: var(--deep-teal);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1px;
}

button {
  border: 0;
  border-radius: 8px;
  padding: 8px 12px;
  background: var(--deep-teal);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}
